# type-driven actions: the selection's type picks the menu
registry = {
    'text': ['Bold', 'Italic', 'Link', 'Quote'],
    'code': ['Format', 'Refactor', 'Run'],
    'image': ['Crop', 'Filter', 'Alt text'],
    'multi': ['Group', 'Align', 'Distribute'],
    'empty': ['Insert text', 'Insert image', 'Paste'],
}

def actions_for(sel_type, sel_count=1):
    if sel_count > 1:
        return registry['multi']
    return registry.get(sel_type, registry['empty'])

for t in ('text', 'code', 'image', 'empty'):
    print('%-6s -> %s' % (t, actions_for(t)))
print('multi-select ->', actions_for('text', 3))

# heuristic suggestions: content features -> likely action
def suggest(text):
    t = text.strip()
    if t.startswith(('http://', 'https://')):
        return 'Open link'
    if '\n' in t and any(c in t for c in '{};'):
        return 'Format code'
    if len(t.split()) > 50:
        return 'Summarize'
    return None

for s in ('https://example.com', 'if(x){y();}', 'word ' * 60, 'hi'):
    print('%-28r -> %s' % (s[:26], suggest(s) or '(no suggestion: plain menu)'))
print('wrong guesses cost nothing: the suggestion is a hint')

# placement solver: ranked candidates, first with acceptable clipping wins
def place(anchor, size, viewport=(800, 600)):
    ax, ay, aw, ah = anchor
    w, h = size
    vw, vh = viewport
    cands = [
        ('above', ax, ay - h - 8), ('below', ax, ay + ah + 8),
        ('left', ax - w - 8, ay), ('right', ax + aw + 8, ay),
    ]
    for name, x, y in cands:
        visible = max(0, min(x + w, vw) - max(x, 0)) * max(0, min(y + h, vh) - max(y, 0))
        if visible >= w * h * 0.9:
            return name, (max(0, min(x, vw - w)), max(0, min(y, vh - h)))
    return 'above-clipped', (ax, max(0, ay - h - 8))

print('anchor near top:', place((100, 10, 80, 20), (160, 120))[0], '(flips below)')
print('anchor mid:', place((100, 300, 80, 20), (160, 120))[0])

