# aggregate: which actions earn their place? (never log selection contents)
events = [
    ('opened', None), ('picked', 'Bold'), ('opened', None), ('dismissed', None),
    ('opened', None), ('picked', 'Link'), ('opened', None), ('picked', 'Bold'),
]
opens = sum(1 for e, _ in events if e == 'opened')
picks = {}
for e, a in events:
    if e == 'picked':
        picks[a] = picks.get(a, 0) + 1
dismiss = sum(1 for e, _ in events if e == 'dismissed')
print('opens: %d, picks: %s, dismiss rate: %.0f%%' % (opens, picks, dismiss/opens*100))
print('high dismiss + low pick -> fix the trigger or prune the actions')

